-- Company-maintained industry classification, initialized from documented POI paths.
-- Store rows keep one dictionary code; original multi-category source remains in import audit.
UPDATE data_dictionary SET remark='门店行业分类：大类/中类/小类；来源分类不等同于自助、连锁等经营模式',
 allow_new_items=TRUE,revision=revision+1,updated_by='SYSTEM'
 WHERE tenant_key='GLOBAL' AND dictionary_code='CRM_STORE_TYPE' AND deleted=0;
